use std::collections::{BTreeMap, HashMap, VecDeque};
use std::io::Read;

const QTY_MAX: u64 = 1_000_000;
const PRICE_MAX: u64 = 100_000;
const ID_MAX: u64 = 9_999_999;

#[derive(Clone, Copy, PartialEq)]
enum Tif {
    Gtc,
    Ioc,
    Fok,
}

struct Order {
    trader: String,
    buy: bool,
    price: u64,
    qty: u64,
}

struct Engine {
    orders: HashMap<u64, Order>,
    bids: BTreeMap<u64, VecDeque<u64>>,
    asks: BTreeMap<u64, VecDeque<u64>>,
    next_id: u64,
    pos: BTreeMap<String, (i64, i64)>,
    out: String,
    failed: bool,
}

fn num(s: &str, lo: u64, hi: u64) -> Option<u64> {
    if s.is_empty() || s.len() > 18 || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let v: u64 = s.parse().ok()?;
    if v >= lo && v <= hi {
        Some(v)
    } else {
        None
    }
}

fn parse_id(s: &str) -> Option<u64> {
    if s.len() > 7 {
        return None;
    }
    num(s, 1, ID_MAX)
}

impl Engine {
    fn new() -> Self {
        Engine {
            orders: HashMap::new(),
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
            next_id: 1,
            pos: BTreeMap::new(),
            out: String::new(),
            failed: false,
        }
    }

    fn emit(&mut self, s: &str) {
        if s.starts_with("error:") {
            self.failed = true;
        }
        self.out.push_str(s);
        self.out.push('\n');
    }

    fn side_of(&mut self, buy: bool) -> &mut BTreeMap<u64, VecDeque<u64>> {
        if buy {
            &mut self.bids
        } else {
            &mut self.asks
        }
    }

    fn crosses(buy: bool, limit: Option<u64>, p: u64) -> bool {
        match limit {
            None => true,
            Some(l) => {
                if buy {
                    p <= l
                } else {
                    p >= l
                }
            }
        }
    }

    /// Removes a resting order from the book and returns it.
    fn remove_resting(&mut self, id: u64) -> Order {
        let o = self.orders.remove(&id).unwrap();
        let side = self.side_of(o.buy);
        let empty = match side.get_mut(&o.price) {
            Some(dq) => {
                if let Some(i) = dq.iter().position(|&x| x == id) {
                    dq.remove(i);
                }
                dq.is_empty()
            }
            None => false,
        };
        if empty {
            side.remove(&o.price);
        }
        o
    }

    fn transfer(&mut self, buyer: &str, seller: &str, q: u64, price: u64) {
        let (q, cash) = (q as i64, (q * price) as i64);
        let b = self.pos.entry(buyer.to_string()).or_insert((0, 0));
        b.0 += q;
        b.1 -= cash;
        let s = self.pos.entry(seller.to_string()).or_insert((0, 0));
        s.0 -= q;
        s.1 += cash;
    }

    fn submit(&mut self, trader: &str, buy: bool, qty: u64, limit: Option<u64>, tif: Tif) {
        let id = self.next_id;
        self.next_id += 1;
        self.pos.entry(trader.to_string()).or_insert((0, 0));
        self.emit(&format!("order {}", id));

        if tif == Tif::Fok {
            let mut avail = 0;
            let opp = if buy { &self.asks } else { &self.bids };
            for (&p, dq) in opp.iter() {
                if Self::crosses(buy, limit, p) {
                    for rid in dq {
                        let o = &self.orders[rid];
                        if o.trader != trader {
                            avail += o.qty;
                        }
                    }
                }
            }
            if avail < qty {
                self.emit(&format!("reject {} fok", id));
                return;
            }
        }

        let mut rem = qty;
        while rem > 0 {
            let best = {
                let opp = if buy { &self.asks } else { &self.bids };
                let p = if buy {
                    opp.keys().next().copied()
                } else {
                    opp.keys().next_back().copied()
                };
                p.filter(|&p| Self::crosses(buy, limit, p))
            };
            let Some(price) = best else { break };
            let rid = *self.side_of(!buy).get(&price).unwrap().front().unwrap();
            let rtrader = self.orders[&rid].trader.clone();
            if rtrader == trader {
                self.remove_resting(rid);
                self.emit(&format!("cancel {} self-trade", rid));
                continue;
            }
            let rqty = self.orders[&rid].qty;
            let q = rem.min(rqty);
            let (bid_id, ask_id) = if buy { (id, rid) } else { (rid, id) };
            let (buyer, seller) = if buy {
                (trader, rtrader.as_str())
            } else {
                (rtrader.as_str(), trader)
            };
            self.emit(&format!("trade {} {} {} @ {}", bid_id, ask_id, q, price));
            self.transfer(buyer, seller, q, price);
            rem -= q;
            if q == rqty {
                self.remove_resting(rid);
            } else {
                self.orders.get_mut(&rid).unwrap().qty -= q;
            }
        }

        if rem == 0 {
            return;
        }
        match (tif, limit) {
            (Tif::Gtc, Some(p)) => {
                self.side_of(buy).entry(p).or_default().push_back(id);
                self.orders.insert(
                    id,
                    Order {
                        trader: trader.to_string(),
                        buy,
                        price: p,
                        qty: rem,
                    },
                );
                self.emit(&format!("rest {} {}", id, rem));
            }
            _ => self.emit(&format!("drop {} {}", id, rem)),
        }
    }

    fn cancel(&mut self, trader: &str, id: u64) {
        let Some((owner, rem)) = self.orders.get(&id).map(|o| (o.trader.clone(), o.qty)) else {
            return self.emit(&format!("error: no such order {}", id));
        };
        if owner != trader {
            return self.emit("error: not owner");
        }
        self.remove_resting(id);
        self.emit(&format!("cancelled {} {}", id, rem));
    }

    fn amend(&mut self, trader: &str, id: u64, q: u64) {
        let Some((owner, cur)) = self.orders.get(&id).map(|o| (o.trader.clone(), o.qty)) else {
            return self.emit(&format!("error: no such order {}", id));
        };
        if owner != trader {
            return self.emit("error: not owner");
        }
        if q > cur {
            let o = self.remove_resting(id);
            let (buy, price) = (o.buy, o.price);
            self.side_of(buy).entry(price).or_default().push_back(id);
            self.orders.insert(id, Order { qty: q, ..o });
        } else {
            self.orders.get_mut(&id).unwrap().qty = q;
        }
        self.emit(&format!("amended {} {}", id, q));
    }

    fn book_lines(&self, buy: bool) -> Vec<String> {
        let side = if buy { &self.bids } else { &self.asks };
        let mut v = Vec::new();
        for (p, dq) in side.iter().rev() {
            let total: u64 = dq.iter().map(|id| self.orders[id].qty).sum();
            v.push(format!("  {} {} {}", p, total, dq.len()));
        }
        if v.is_empty() {
            v.push("  (none)".to_string());
        }
        v
    }

    fn print_book(&mut self) {
        let mut lines = vec!["asks:".to_string()];
        lines.extend(self.book_lines(false));
        lines.push("bids:".to_string());
        lines.extend(self.book_lines(true));
        for l in lines {
            self.emit(&l);
        }
    }

    fn print_pos(&mut self) {
        if self.pos.is_empty() {
            self.emit("(no traders)");
            return;
        }
        let lines: Vec<String> = self
            .pos
            .iter()
            .map(|(n, (q, c))| format!("{} {} {}", n, q, c))
            .collect();
        for l in lines {
            self.emit(&l);
        }
    }

    fn command(&mut self, line: &str) {
        let f: Vec<&str> = line.split_whitespace().collect();
        if f.is_empty() {
            return;
        }
        let cmd = f[0];
        match cmd {
            "book" if f.len() == 1 => self.print_book(),
            "pos" if f.len() == 1 => self.print_pos(),
            "cancel" if f.len() == 3 => match parse_id(f[2]) {
                Some(id) => self.cancel(f[1], id),
                None => self.emit("error: bad command"),
            },
            "amend" if f.len() == 4 => match (parse_id(f[2]), num(f[3], 1, QTY_MAX)) {
                (Some(id), Some(q)) => self.amend(f[1], id, q),
                _ => self.emit("error: bad command"),
            },
            "buy" | "sell" if f.len() == 4 || f.len() == 5 => {
                let tif = if f.len() == 5 {
                    match f[4] {
                        "ioc" => Some(Tif::Ioc),
                        "fok" => Some(Tif::Fok),
                        _ => None,
                    }
                } else {
                    Some(Tif::Gtc)
                };
                match (num(f[2], 1, QTY_MAX), num(f[3], 1, PRICE_MAX), tif) {
                    (Some(q), Some(p), Some(tif)) => {
                        self.submit(f[1], cmd == "buy", q, Some(p), tif)
                    }
                    _ => self.emit("error: bad command"),
                }
            }
            "mbuy" | "msell" if f.len() == 3 => match num(f[2], 1, QTY_MAX) {
                Some(q) => self.submit(f[1], cmd == "mbuy", q, None, Tif::Ioc),
                None => self.emit("error: bad command"),
            },
            _ => self.emit("error: bad command"),
        }
    }
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    let mut e = Engine::new();
    for line in input.lines() {
        e.command(line);
    }
    print!("{}", e.out);
    if e.failed {
        std::process::exit(1);
    }
}

